package suite

import "base:intrinsics"
import "core:bufio"

// The calculator is an operator-precedence (shunting-yard) evaluator with explicit
// stacks, so deeply nested input cannot exhaust the call stack.

Op :: enum u8 {
	Add,
	Sub,
	Mul,
	Div,
	Mod,
	Neg,
	Paren, // an open parenthesis awaiting its match
}

@(rodata)
OP_PRECEDENCE := [Op]u8 {
	.Paren = 0,
	.Add   = 1,
	.Sub   = 1,
	.Mul   = 2,
	.Div   = 2,
	.Mod   = 2,
	.Neg   = 3,
}

Calc :: struct {
	values: [dynamic]i64,
	ops:    [dynamic]Op,
}

calc_destroy :: proc(c: ^Calc) {
	delete(c.values)
	delete(c.ops)
}

// calc_run evaluates each non-blank line of input and prints its value or "error".
calc_run :: proc(input: string, out: ^bufio.Writer) {
	c: Calc
	defer calc_destroy(&c)

	rest := input
	for line in split_line(&rest) {
		if is_blank(line) {
			continue
		}
		if v, ok := calc_eval(&c, line); ok {
			write_int(out, v)
			bufio.writer_write_byte(out, '\n')
		} else {
			write_line(out, "error")
		}
	}
}

is_blank :: proc(s: string) -> bool {
	for b in transmute([]byte)s {
		if b != ' ' && b != '\t' {
			return false
		}
	}
	return true
}

// calc_eval evaluates one expression. ok is false on a syntax error, division by
// zero, or 64-bit overflow.
calc_eval :: proc(c: ^Calc, s: string) -> (result: i64, ok: bool) {
	clear(&c.values)
	clear(&c.ops)

	expect_operand := true
	i := 0
	for {
		for i < len(s) && (s[i] == ' ' || s[i] == '\t') {
			i += 1
		}
		if i == len(s) {
			break
		}
		ch := s[i]

		if expect_operand {
			switch ch {
			case '-':
				append(&c.ops, Op.Neg)
				i += 1
			case '(':
				append(&c.ops, Op.Paren)
				i += 1
			case '0' ..= '9':
				v: i64
				for i < len(s) && s[i] >= '0' && s[i] <= '9' {
					overflow_mul, overflow_add: bool
					v, overflow_mul = intrinsics.overflow_mul(v, 10)
					v, overflow_add = intrinsics.overflow_add(v, i64(s[i] - '0'))
					if overflow_mul || overflow_add {
						return 0, false // literal exceeds max(i64)
					}
					i += 1
				}
				append(&c.values, v)
				expect_operand = false
			case:
				return 0, false
			}
			continue
		}

		op: Op
		switch ch {
		case '+': op = .Add
		case '-': op = .Sub
		case '*': op = .Mul
		case '/': op = .Div
		case '%': op = .Mod
		case ')':
			for {
				top := pop_safe(&c.ops) or_return
				if top == .Paren {
					break
				}
				apply(c, top) or_return
			}
			i += 1
			continue
		case:
			return 0, false
		}
		// All binary operators are left-associative: reduce everything that binds at
		// least as tightly before pushing.
		for len(c.ops) > 0 {
			top := c.ops[len(c.ops) - 1]
			if OP_PRECEDENCE[top] < OP_PRECEDENCE[op] {
				break
			}
			pop(&c.ops)
			apply(c, top) or_return
		}
		append(&c.ops, op)
		expect_operand = true
		i += 1
	}

	if expect_operand {
		return 0, false // empty input or a dangling operator
	}
	for len(c.ops) > 0 {
		top := pop(&c.ops)
		if top == .Paren {
			return 0, false // unclosed parenthesis
		}
		apply(c, top) or_return
	}
	if len(c.values) != 1 {
		return 0, false
	}
	return c.values[0], true
}

// apply pops the operands of op from the value stack and pushes its result.
@(private = "file")
apply :: proc(c: ^Calc, op: Op) -> bool {
	if op == .Neg {
		n := len(c.values)
		if n < 1 {
			return false
		}
		v := c.values[n - 1]
		if v == min(i64) {
			return false
		}
		c.values[n - 1] = -v
		return true
	}

	n := len(c.values)
	if n < 2 {
		return false
	}
	a, b := c.values[n - 2], c.values[n - 1]
	r: i64
	overflow: bool
	#partial switch op {
	case .Add:
		r, overflow = intrinsics.overflow_add(a, b)
	case .Sub:
		r, overflow = intrinsics.overflow_sub(a, b)
	case .Mul:
		r, overflow = intrinsics.overflow_mul(a, b)
	case .Div:
		if b == 0 || (a == min(i64) && b == -1) {
			return false
		}
		r = a / b
	case .Mod:
		if b == 0 {
			return false
		}
		r = 0 if b == -1 else a % b
	case:
		return false
	}
	if overflow {
		return false
	}
	resize(&c.values, n - 1)
	c.values[n - 2] = r
	return true
}

package suite

import "core:bufio"
import "core:strconv"
import "core:strings"

// LRU cache of string keys to string values. Entries live in a node pool linked into a
// circular doubly-linked recency list through a sentinel at index 0: sentinel.next is the
// most recently used entry, sentinel.prev the least. Keys and values borrow the input.
Lru :: struct {
	capacity: int,
	index:    map[string]u32,
	nodes:    [dynamic]Lru_Node,
	free:     [dynamic]u32,
}

Lru_Node :: struct {
	key, value: string,
	prev, next: u32,
}

SENTINEL :: 0

lru_init :: proc(c: ^Lru, capacity: int) {
	c.capacity = capacity
	initial := min(capacity, 1 << 16)
	c.index = make(map[string]u32, initial)
	c.nodes = make([dynamic]Lru_Node, 1, initial + 1)
	c.free = make([dynamic]u32)
}

lru_destroy :: proc(c: ^Lru) {
	delete(c.index)
	delete(c.nodes)
	delete(c.free)
}

lru_len :: proc(c: ^Lru) -> int {
	return len(c.index)
}

@(private = "file")
unlink :: proc(c: ^Lru, i: u32) {
	n := &c.nodes[i]
	c.nodes[n.prev].next = n.next
	c.nodes[n.next].prev = n.prev
}

@(private = "file")
push_front :: proc(c: ^Lru, i: u32) {
	first := c.nodes[SENTINEL].next
	c.nodes[i].prev = SENTINEL
	c.nodes[i].next = first
	c.nodes[first].prev = i
	c.nodes[SENTINEL].next = i
}

@(private = "file")
release :: proc(c: ^Lru, i: u32) {
	unlink(c, i)
	delete_key(&c.index, c.nodes[i].key)
	c.nodes[i] = {}
	append(&c.free, i)
}

lru_set :: proc(c: ^Lru, key, value: string) {
	if i, ok := c.index[key]; ok {
		c.nodes[i].value = value
		unlink(c, i)
		push_front(c, i)
		return
	}
	if lru_len(c) >= c.capacity {
		release(c, c.nodes[SENTINEL].prev)
	}
	i: u32
	if len(c.free) > 0 {
		i = pop(&c.free)
	} else {
		i = u32(len(c.nodes))
		append(&c.nodes, Lru_Node{})
	}
	c.nodes[i].key = key
	c.nodes[i].value = value
	push_front(c, i)
	c.index[key] = i
}

lru_get :: proc(c: ^Lru, key: string) -> (value: string, ok: bool) {
	i := c.index[key] or_return
	unlink(c, i)
	push_front(c, i)
	return c.nodes[i].value, true
}

lru_del :: proc(c: ^Lru, key: string) -> bool {
	i := c.index[key] or_return
	release(c, i)
	return true
}

// lru_run executes the commands in input (capacity on the first line, then one
// command per line) and writes each command's output on its own line.
// Malformed or unknown commands are ignored.
lru_run :: proc(input: string, out: ^bufio.Writer) {
	rest := input
	first, _ := split_line(&rest)
	capacity, ok := strconv.parse_int(strings.trim_space(first), 10)
	if !ok || capacity < 1 {
		return
	}

	cache: Lru
	lru_init(&cache, capacity)
	defer lru_destroy(&cache)

	for line in split_line(&rest) {
		cmd, _, args := strings.partition(line, " ")
		switch cmd {
		case "SET":
			key, _, value := strings.partition(args, " ")
			if key != "" && value != "" {
				lru_set(&cache, key, value)
			}
		case "GET":
			if value, hit := lru_get(&cache, args); hit {
				write_line(out, value)
			} else {
				write_line(out, "NULL")
			}
		case "DEL":
			write_line(out, "1" if lru_del(&cache, args) else "0")
		case "SIZE":
			write_int(out, i64(lru_len(&cache)))
			bufio.writer_write_byte(out, '\n')
		}
	}
}

// suite: a command-line program bundling three independent stdin→stdout tools.
//
//	./app wordfreq   top-10 word frequencies
//	./app lru        LRU cache simulator
//	./app calc       64-bit integer expression evaluator
package suite

import "core:bufio"
import "core:fmt"
import "core:os"
import "core:strconv"

USAGE :: "usage: app (wordfreq | lru | calc) < input\n"

main :: proc() {
	if len(os.args) != 2 {
		fmt.eprint(USAGE)
		os.exit(2)
	}

	input, err := read_all_stdin()
	if err != nil {
		fmt.eprintfln("app: reading standard input: %v", err)
		os.exit(1)
	}

	out: bufio.Writer
	bufio.writer_init(&out, os.to_stream(os.stdout), 64 * 1024)
	defer bufio.writer_destroy(&out)

	switch os.args[1] {
	case "wordfreq":
		wordfreq_run(input, &out)
	case "lru":
		lru_run(string(input), &out)
	case "calc":
		calc_run(string(input), &out)
	case:
		fmt.eprint(USAGE)
		os.exit(2)
	}

	if ferr := bufio.writer_flush(&out); ferr != nil {
		fmt.eprintfln("app: writing standard output: %v", ferr)
		os.exit(1)
	}
}

// read_all_stdin reads standard input to EOF. Standard input is usually a pipe, whose
// size is unknown, so it is read in large chunks into a buffer that doubles as needed.
read_all_stdin :: proc(allocator := context.allocator) -> (data: []byte, err: os.Error) {
	CHUNK :: 1 << 20
	buf := make([]byte, 4 * CHUNK, allocator) or_return
	n := 0
	for {
		if len(buf) - n < CHUNK {
			grown := make([]byte, 2 * len(buf), allocator) or_return
			copy(grown, buf[:n])
			delete(buf, allocator)
			buf = grown
		}
		read, rerr := os.read(os.stdin, buf[n:])
		n += read
		if rerr == .EOF || (rerr == nil && read == 0) {
			break
		}
		if rerr != nil {
			delete(buf, allocator)
			return nil, rerr
		}
	}
	return buf[:n], nil
}

// write_line writes s followed by a newline.
write_line :: proc(w: ^bufio.Writer, s: string) {
	bufio.writer_write_string(w, s)
	bufio.writer_write_byte(w, '\n')
}

// write_int writes the decimal form of v without a newline.
write_int :: proc(w: ^bufio.Writer, v: i64) {
	digits: [32]byte
	bufio.writer_write_string(w, strconv.write_int(digits[:], v, 10))
}

// split_line removes the first line from s and returns it without its terminator
// (a trailing '\r' is dropped as well). ok is false once s is exhausted.
split_line :: proc(s: ^string) -> (line: string, ok: bool) {
	if len(s^) == 0 {
		return "", false
	}
	end := len(s^)
	next := end
	for i in 0 ..< len(s^) {
		if s[i] == '\n' {
			end, next = i, i + 1
			break
		}
	}
	line = s[:end]
	s^ = s[next:]
	if len(line) > 0 && line[len(line) - 1] == '\r' {
		line = line[:len(line) - 1]
	}
	return line, true
}

package suite

import "core:bufio"

TOP_WORDS :: 10

Word_Count :: struct {
	word:  string,
	count: int,
}

// wordfreq_run prints the TOP_WORDS most frequent words of data, most frequent first,
// ties broken by ascending byte order. A word is a maximal run of ASCII letters,
// compared case-insensitively. data is lowercased in place so words can borrow it.
wordfreq_run :: proc(data: []byte, out: ^bufio.Writer) {
	counts := make(map[string]int, 1 << 14)
	defer delete(counts)

	i := 0
	n := len(data)
	for i < n {
		for i < n && !is_letter(data[i]) {
			i += 1
		}
		start := i
		for i < n && is_letter(data[i]) {
			data[i] |= 0x20 // for ASCII letters, setting bit 5 lowercases
			i += 1
		}
		if i > start {
			counts[string(data[start:i])] += 1
		}
	}

	// Select the top entries with an insertion-sorted fixed array: O(distinct words).
	top: [TOP_WORDS]Word_Count
	held := 0
	for word, count in counts {
		e := Word_Count{word, count}
		if held == TOP_WORDS && !ranks_before(e, top[held - 1]) {
			continue
		}
		j := min(held, TOP_WORDS - 1)
		for j > 0 && ranks_before(e, top[j - 1]) {
			top[j] = top[j - 1]
			j -= 1
		}
		top[j] = e
		held = min(held + 1, TOP_WORDS)
	}

	for e in top[:held] {
		write_int(out, i64(e.count))
		bufio.writer_write_byte(out, ' ')
		write_line(out, e.word)
	}
}

// ranks_before orders by count descending, then word ascending.
ranks_before :: proc(a, b: Word_Count) -> bool {
	if a.count != b.count {
		return a.count > b.count
	}
	return a.word < b.word
}

is_letter :: #force_inline proc "contextless" (b: byte) -> bool {
	return (b | 0x20) - 'a' < 26
}
